@'
import fs from "fs";
import path from "path";
const root = path.join(process.env.USERPROFILE, ".openviking/data/viking/default/user/default/memories");
const weird = [];
const overview = [];
function walk(d, rel=""){
  for (const e of fs.readdirSync(d, {withFileTypes:true})) {
    const p = path.join(d, e.name);
    const r = rel ? rel+"/"+e.name : e.name;
    if (e.isDirectory()) {
      if (/padrão|estrutura|projeto de|portugu/i.test(r)) weird.push("dir:"+r);
      walk(p, r);
    } else if (e.name.endsWith(".md")) {
      if (e.name === ".overview.md" || e.name === "overview.md") overview.push(r);
      const raw = fs.readFileSync(p,"utf8");
      const body = raw.replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g,"").trim();
      if (/^# Entities Overview\s*\*\*Category:\*\*/.test(body.slice(0,200))) overview.push(r+" (index)");
    }
  }
}
walk(root);
console.log("foreign-ish paths:", weird.length);
weird.slice(0,15).forEach(x=>console.log(" ",x));
console.log("overview/index cards:", overview.length);
console.log("sample:", overview.slice(0,8).join("\n  "));
'@ | Set-Content "$env:TEMP\mem-audit2.mjs" -Encoding UTF8; node "$env:TEMP\mem-audit2.mjs"

@'
import fs from "fs";
import path from "path";
const root = path.join(process.env.USERPROFILE, ".openviking/data/viking/default/user/default/memories/entities");
const titles = new Map();
function norm(s){ return s.replace(/\s+/g,"").toLowerCase().slice(0,40); }
function walk(d){
  for (const e of fs.readdirSync(d, {withFileTypes:true})) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md") && !e.name.startsWith(".overview")) {
      const body = fs.readFileSync(p,"utf8").replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g,"");
      const h1 = (body.match(/^#\s+(.+)/m)||[])[1]||"";
      const key = norm(h1 || path.basename(e.name,".md"));
      if (!titles.has(key)) titles.set(key, []);
      titles.get(key).push(path.relative(root,p).replace(/\\/g,"/"));
    }
  }
}
if (fs.existsSync(root)) walk(root);
const near = [...titles.entries()].filter(([,v])=>v.length>1).sort((a,b)=>b[1].length-a[1].length);
console.log("near-dup by H1 (entities only):", near.length, "groups");
for (const [k,v] of near.slice(0,15)) console.log(" ",v.length, k.slice(0,30), "->", v.join(" | "));
'@ | Set-Content "$env:TEMP\mem-audit3.mjs" -Encoding UTF8; node "$env:TEMP\mem-audit3.mjs"

@'
import fs from "fs";
import path from "path";
const root = path.join(process.env.USERPROFILE, ".openviking/data/viking/default/user/default/memories");
let legacy=0, stale=0, test=0;
function walk(d){
  for (const e of fs.readdirSync(d, {withFileTypes:true})) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md")) {
      const t = fs.readFileSync(p,"utf8");
      if (/long-term-memory|long_term_memory_library|零填充|已废弃/.test(t)) legacy++;
      if (/test_env|placeholder|TODO|FIXME|lorem/i.test(t) && t.length<500) test++;
    }
  }
}
walk(root);
console.log("mentions legacy ltm:", legacy);
console.log("possible test/placeholder short:", test);
'@ | Set-Content "$env:TEMP\mem-audit4.mjs" -Encoding UTF8; node "$env:TEMP\mem-audit4.mjs"

